CREATE TABLE merchants (id BIGINT PRIMARY KEY AUTO_INCREMENT, business_name VARCHAR(180) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, merchant_id BIGINT NULL, email VARCHAR(254) NOT NULL UNIQUE, role VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_users_merchant FOREIGN KEY(merchant_id) REFERENCES merchants(id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE customers (id BIGINT PRIMARY KEY AUTO_INCREMENT, merchant_id BIGINT NOT NULL, full_name VARCHAR(180) NOT NULL, email VARCHAR(254), phone VARCHAR(32), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_customers_merchant FOREIGN KEY(merchant_id) REFERENCES merchants(id), INDEX idx_customer_merchant(merchant_id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE plans (id BIGINT PRIMARY KEY AUTO_INCREMENT, merchant_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, status VARCHAR(24) NOT NULL, total_amount_paise BIGINT NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'INR', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_plans_merchant FOREIGN KEY(merchant_id) REFERENCES merchants(id), CONSTRAINT fk_plans_customer FOREIGN KEY(customer_id) REFERENCES customers(id), INDEX idx_plans_merchant_status(merchant_id,status)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE installments (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, merchant_id BIGINT NOT NULL, status VARCHAR(24) NOT NULL, amount_paise BIGINT NOT NULL, due_date DATE NOT NULL, paid_at TIMESTAMP NULL, CONSTRAINT fk_inst_plan FOREIGN KEY(plan_id) REFERENCES plans(id), CONSTRAINT fk_inst_merchant FOREIGN KEY(merchant_id) REFERENCES merchants(id), INDEX idx_inst_merchant_status_due(merchant_id,status,due_date)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, amount_paise BIGINT NOT NULL, status VARCHAR(24) NOT NULL, reference VARCHAR(120), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_pay_plan FOREIGN KEY(plan_id) REFERENCES plans(id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE plan_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, event_type VARCHAR(60) NOT NULL, detail JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_events_plan FOREIGN KEY(plan_id) REFERENCES plans(id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE otp_codes (id BIGINT PRIMARY KEY AUTO_INCREMENT, identifier_hash CHAR(64) NOT NULL, channel VARCHAR(16) NOT NULL, purpose VARCHAR(24) NOT NULL, code_hash CHAR(64) NOT NULL, expires_at TIMESTAMP NOT NULL, attempts INT NOT NULL DEFAULT 0, consumed_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ip VARCHAR(64), INDEX idx_otp_identifier(identifier_hash,purpose,created_at)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE refresh_tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, family_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP NULL, replaced_by BIGINT NULL, created_ip VARCHAR(64), user_agent VARCHAR(512), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_refresh_replaced FOREIGN KEY(replaced_by) REFERENCES refresh_tokens(id), INDEX idx_refresh_family(family_id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE magic_links (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP NULL, revoked_at TIMESTAMP NULL, CONSTRAINT fk_magic_plan FOREIGN KEY(plan_id) REFERENCES plans(id), CONSTRAINT fk_magic_customer FOREIGN KEY(customer_id) REFERENCES customers(id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE login_attempts (id BIGINT PRIMARY KEY AUTO_INCREMENT, identifier_hash CHAR(64) NOT NULL, ip VARCHAR(64), success BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_attempt_lock(identifier_hash,created_at)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, event_type VARCHAR(48) NOT NULL, email_masked VARCHAR(254), ip VARCHAR(64), user_agent VARCHAR(512), detail JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_type_created(event_type,created_at)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE idempotency_keys (id BIGINT PRIMARY KEY AUTO_INCREMENT, scope_key VARCHAR(180) NOT NULL UNIQUE, response_json JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
